// В серверном коде вашего элемента, на этом компьютере: порт и ключ узла даёт узел
const base = `http://127.0.0.1:${port}`
const headers = { 'content-type': 'application/json', 'X-Node-Key': process.env.SETTINGS_SECRET }
// from: id вашего элемента
await fetch(`${base}/v1/remember`, { method: 'POST', headers, body: JSON.stringify({ text: 'такси из аэропорта стоило 40 евро', from: ['my-element'] }) })
const answer = await fetch(`${base}/v1/recall`, { method: 'POST', headers, body: JSON.stringify({ text: 'сколько стоило такси?', from: ['my-element'] }) }).then((r) => r.json())
